-- ============================================================================
-- Bewertungsstufen der 20 Verhalten (Plan §5.1: verhalten_kriterien)
--
-- Quelle: referenz/umfrage-dawiid.html (CONFIG.verhalten[].kriterien), Wort für Wort
-- übernommen. Die Migration ist wiederholbar und aktualisiert vorhandene Stufen.
-- Videos sind in der Vorlage noch nicht hinterlegt (video: ''), deshalb bleibt video_url leer.
-- ============================================================================

insert into public.verhalten_kriterien (verhalten_id, stufe, bezeichnung, prozent, leitsatz, punkte)
select v.id, k.stufe, k.bezeichnung, k.prozent, k.leitsatz, k.punkte
from public.verhalten v
join public.salons s on s.id = v.salon_id and s.name = 'Dawiid'
join (values
  (1, 1, '1 – Bewusstsein', '0–25%', 'Beginnt, Unterbrechungen im Kundenmoment bewusster wahrzunehmen.', array['spricht Kollegen teilweise noch direkt am Platz an', 'entscheidet situativ, ob etwas angesprochen wird', 'bittet den Gast vereinzelt um Erlaubnis']::text[]),
  (1, 2, '2 – Aufbau', '25–50%', 'Baut Routine auf und entwickelt ein klares Gefühl dafür, wie Unterbrechungen das Erlebnis beeinflussen.', array['bittet meist um Erlaubnis', 'denkt in vielen Situationen daran', 'bittet den Gast mit einer kurzen, wiederkehrenden Standardformulierung um Erlaubnis', 'nutzt teilweise die Watch als Kommunikationsweg']::text[]),
  (1, 3, '3 – Stabilität', '50–75%', 'Stört nur noch situativ selten und wahrt dabei klare Haltung.', array['bittet den Gast klar und respektvoll um Erlaubnis', 'formuliert kurz und präzise', 'hält ruhige Körpersprache und klare Präsenz', 'leitet die meisten Informationen über die Watch weiter']::text[]),
  (1, 4, '4 – Sehr gut', '75–100%', 'Stört nahezu nie, da interne Abstimmungen primär über die Uhr laufen. Wenn eine direkte Ansprache notwendig ist, geschieht sie so ruhig und souverän, dass der Gast Professionalität wahrnimmt.', array['diskrete, kurze Nachfrage', 'ggf. nonverbales Erfragen über Mimik', 'bei lesendem Gast z. B. leichte Berührung an der Schulter', 'ruhige, aufrechte Haltung', 'klärt interne Punkte konsequent über Watch']::text[]),
  (1, 5, '5 – Prägend / High Performer', '110%', 'Lebt diese Priorität so selbstverständlich, dass Unterbrechungen nicht entstehen und setzt damit Orientierung fürs Team.', array['erfüllt konsequent alle Kriterien aus Stufe 4', 'strahlt ruhige Präsenz und klare Haltung aus', 'wirkt orientierend für Gäste und Team', 'Unterbrechungen entstehen nicht, weil Bewusstsein und Haltung konstant sind']::text[]),
  (2, 1, '1 – Bewusstsein', '0–25%', 'Beginnt, die eigene Wirkung auf den Gast bewusster zu steuern.', array['arbeitet daran, Bewegungen ruhiger zu gestalten', 'entwickelt ein Gespür für Mimik und Körpersprache', 'reflektiert eigene Reaktionen bei erhöhtem Aufkommen', 'trennt interne Themen zunehmend bewusster vom Kundenkontakt']::text[]),
  (2, 2, '2 – Aufbau', '25–50%', 'Zeigt bereits oft professionelle Ruhe und baut spürbar Stabilität auf.', array['bemüht sich um kontrollierte Bewegungen', 'achtet bewusst auf Tonalität', 'erklärt Abläufe strukturierter']::text[]),
  (2, 3, '3 – Stabilität', '50–75%', 'Bleibt auch bei erhöhtem Aufkommen oder zeitlichem Verzug überwiegend ruhig und kontrolliert.', array['stabile Haltung und klare Präsenz', 'ruhige, sachliche Wortwahl', 'strukturierte Handlungsabfolge', 'löst kleinere Herausforderungen ohne sichtbare Unruhe']::text[]),
  (2, 4, '4 – Profi', '75–100%', 'Strahlt selbst bei Fehlern, Zeitdruck oder unerwarteten Situationen Souveränität aus.', array['ruhige, kontrollierte Präsenz', 'klare, entschleunigte Bewegungen', 'lösungsorientiertes Handeln ohne Drama', 'hält den Kundenkontakt frei von internen Themen']::text[]),
  (2, 5, '5 – High Performer', '110%', 'Verkörpert Ruhe als Luxus und stabilisiert damit auch das Umfeld.', array['erfüllt konsequent alle Kriterien aus Stufe 4', 'erkennt Spannungen oder Engpässe frühzeitig', 'sorgt dafür, dass Situationen unbemerkt und professionell gelöst werden', 'denkt in Lösungen, nicht in Problemen', 'schützt die Atmosphäre für Gäste und Team']::text[]),
  (3, 1, '1 – Bewusstsein', '0–25%', 'Beginnt, Gesprächsführung als bewussten Teil der Dienstleistung zu verstehen.', array['bringt Beiträge teilweise noch spontan ein', 'entwickelt Bewusstsein für eigenen Redeanteil', 'fragt, was gerade einfällt, statt das Gespräch bewusst zu führen', 'erkennt zunehmend: Gesprächsführung erzeugt Professionalität']::text[]),
  (3, 2, '2 – Aufbau', '25–50%', 'Setzt Gesprächsführung zunehmend bewusst ein und baut Struktur im Austausch auf.', array['stellt gezieltere Fragen', 'achtet häufiger auf ausgewogenen Redeanteil', 'lenkt Gespräche in vielen Situationen aktiv', 'erzeugt bereits spürbare Professionalität']::text[]),
  (3, 3, '3 – Stabilität', '50–75%', 'Führt Gespräche klar, strukturiert und mit Fokus auf den Gast.', array['prüft aktiv die Gesprächsbereitschaft', 'stellt relevante, zielgerichtete Fragen (Gedächtnisprotokoll)', 'hört aufmerksam zu', 'hält eigene Beiträge präzise und dienstleistungsbezogen']::text[]),
  (3, 4, '4 – Profi', '75–100%', 'Moderiert Gespräche ruhig, souverän und mit bewusstem Einsatz des Salon-Vokabulars.', array['ruhiger Ton und kontrollierte Mimik', 'klare, wertschätzende und positive Wortwahl', 'verwendet definiertes Salon-Vokabular selbstverständlich', 'sichere, offene Körperhaltung', 'schafft durch Gesprächsstruktur Distanz, Professionalität und Aufmerksamkeit']::text[]),
  (3, 5, '5 – High Performer', '110%', 'Verkörpert Gesprächsführung mit maximalem Bewusstsein und hebt damit das Teamniveau.', array['erfüllt konsequent alle Kriterien aus Stufe 4', 'nutzt Sprache als Führungsinstrument', 'denkt Gesprächsführung als kulturelles Element', 'wirkt orientierend für Gäste und Team', 'stärkt durch Präsenz und Haltung das Kommunikationsniveau im Salon']::text[]),
  (4, 1, '1 – Bewusstsein', '0–25%', 'Beginnt, die Wirkung von Gesprächsthemen im Salon bewusster wahrzunehmen.', array['bringt Themen teilweise noch spontan ein', 'teilt persönliche Inhalte situativ', 'entwickelt ein erstes Gefühl dafür, welche Inhalte in den Salon passen', 'reflektiert zunehmend die Wirkung eigener Worte im Raum']::text[]),
  (4, 2, '2 – Aufbau', '25–50%', 'Achtet bereits aktiv auf eine professionelle Themenwahl im Kundenbereich.', array['wählt Inhalte überwiegend bewusst', 'hält Gespräche ruhig und angemessen', 'entwickelt mehr Sicherheit in professioneller Themenwahl', 'wirkt in vielen Situationen bereits stabil und strukturiert']::text[]),
  (4, 3, '3 – Stabilität', '50–75%', 'Schützt die Atmosphäre durch klare und bewusste Themenwahl.', array['hält Gespräche salongeeignet und wertig', 'wertet negativ geführte Gespräche von Gästen ruhig um', 'wahrt eine angenehme Grundstimmung im Raum', 'wirkt stabil in Ton, Mimik und Präsenz']::text[]),
  (4, 4, '4 – Profi', '75–100%', 'Lebt professionelle Themenwahl vollständig und gestaltet bewusst eine entspannte Atmosphäre.', array['kommuniziert konsequent nach Kommunikationsleitfaden', 'gibt dem Gast Raum für Stille', 'schafft eine entspannte, fast schon Wellness-Atmosphäre', 'wirkt ruhig, stabil und klar in Präsenz']::text[]),
  (4, 5, '5 – High Performer', '110%', 'Prägt durch Haltung die Gesprächskultur im gesamten Salon und hält die Atmosphäre stabil.', array['erfüllt konsequent alle Kriterien aus Stufe 4', 'reguliert Situationen diskret über passende Kommunikationswege (z. B. Uhr oder Nebenräume)', 'schützt die Atmosphäre aktiv auch im Team', 'wirkt stabilisierend und orientierend']::text[]),
  (5, 1, '1 – Bewusstsein', '0–25%', 'Entdeckt das Waschbecken zunehmend als bewussten Entspannungsmoment im Service.', array['integriert Gespräch und Ablauf aus Gewohnheit', 'arbeitet in natürlichem Arbeitstempo', 'nimmt erste Impulse zur bewussten Entschleunigung wahr', 'entwickelt Sensibilität für Atmosphäre und Wirkung']::text[]),
  (5, 2, '2 – Aufbau', '25–50%', 'Beginnt, den Waschmoment gezielt ruhiger zu gestalten.', array['stellt eigene Kommunikation zurück und lässt den Gast entspannen', 'verlangsamt Bewegungen situativ', 'achtet stärker auf gleichmäßige Abläufe', 'erkennt die Wirkung von Stille und Rhythmus']::text[]),
  (5, 3, '3 – Stabilität', '50–75%', 'Gestaltet das Waschbecken konstant als ruhigen Bestandteil des Erlebnisses.', array['gleichmäßige, kontrollierte Bewegungen', 'bindet Produktinformationen am Waschbecken situativ ein', 'bewusste Kommunikation', 'hält die Atmosphäre verlässlich ruhig']::text[]),
  (5, 4, '4 – Profi', '75–100%', 'Setzt das Waschbecken bewusst als Ruhezone ein.', array['strukturiert den Ablauf vorab am Bedienungsplatz', 'arbeitet in entschleunigtem, kontrolliertem Tempo', 'hält eine ruhige, sichere Haltung', 'schafft einen klar abgegrenzten Entspannungsmoment']::text[]),
  (5, 5, '5 – High Performer', '110%', 'Verankert Entschleunigung als festen Bestandteil des Salonerlebnisses.', array['erfüllt konsequent alle Kriterien aus Stufe 4', 'unterstützt Kollegen aktiv beim Produktwissen', 'schützt die Ruhe auch im Umfeld', 'denkt den Moment bewusst voraus', 'hebt durch Haltung und Präsenz den Standard im Team']::text[]),
  (6, 1, '1 – Bewusstsein', '0–25%', 'Entwickelt zunehmend ein Bewusstsein für Feinfühligkeit, Druck und Sensibilität im Umgang mit Haar und Kopfhaut.', array['findet noch nicht konstant das passende Tempo', 'nimmt Unterschiede in Haarstruktur bewusster wahr', 'beginnt, Druck und Zug bewusster anzupassen', 'entwickelt Sensibilität für individuelle Bedürfnisse']::text[]),
  (6, 2, '2 – Aufbau', '25–50%', 'Baut ein spürbares Feingefühl auf und integriert es zunehmend in den Ablauf.', array['passt Druck bewusster an', 'arbeitet strukturierter und kontrollierter', 'berücksichtigt Haarzustand häufiger aktiv', 'entwickelt Sicherheit im haarschonenden Arbeiten']::text[]),
