  (6, 5, '5 – High Performer', '110%', 'Setzt Maßstab für bewussten Umgang mit Haarqualität im Team.', array['erfüllt konsequent alle Kriterien aus Stufe 4', 'erkennt Belastungsgrenzen frühzeitig und schützt Haarqualität aktiv', 'sensibilisiert Kollegen für denselben Qualitätsanspruch', 'vermittelt dem Gast spürbar Fachwissen und Vertrauen']::text[]),
  (7, 1, '1 – Bewusstsein', '0–25%', 'Entdeckt das System zunehmend als Werkzeug für professionelle Beziehungspflege.', array['nimmt Gästedetails bewusster wahr', 'dokumentiert Informationen situativ', 'erkennt erste Zusammenhänge zwischen Notizen und Servicequalität', 'entwickelt Routine im Umgang mit dem System']::text[]),
