  (7, 3, '3 – Stabilität', '50–75%', 'Arbeitet zuverlässig mit Gästedaten.', array['hält Gästedaten im System aktuell, klar definiert und datiert', 'nutzt Einträge aktiv im Service', 'reduziert Wiederholungsfragen', 'wirkt vorbereitet']::text[]),
  (7, 4, '4 – Profi', '75–100%', 'Hebt durch systematische Dokumentation den Erlebnisstandard.', array['präzise und vollständige Einträge', 'nutzt hinterlegte Informationen gezielt für einen persönlichen und vorbereiteten Start in den Termin', 'der Ablauf wirkt professionell vorbereitet', 'personalisierte Ansprache ist klar erkennbar']::text[]),
  (7, 5, '5 – High Performer', '110%', 'Denkt Beziehungspflege strategisch und prägt damit das Team.', array['erfüllt konsequent alle Kriterien aus Stufe 4', 'denkt bei der Dokumentation teamübergreifend', 'hält relevante Informationen auch für Kollegen nachvollziehbar fest', 'hebt das Erlebnis durch Details sichtbar an']::text[]),
  (8, 1, '1 – Bewusstsein', '0–25%', 'Entwickelt ein bewussteres Gefühl für die Wirkung persönlicher Ansprache.', array['integriert den Namen situativ', 'nimmt Bedeutung und Wirkung bewusster wahr', 'baut Sicherheit im Einsatz der Namensansprache auf', 'entwickelt Gespür für Timing']::text[]),
