  (9, 1, '1 – Bewusstsein', '0–25%', 'Entdeckt das Bücherregal zunehmend als Teil des Salonerlebnisses.', array['nimmt das Regal bewusster wahr', 'erwähnt es situativ im Gespräch', 'erkennt erste Anknüpfungspunkte zu Interessen des Gastes', 'entwickelt Verständnis für den kulturellen Mehrwert']::text[]),
